<?php
namespace App\Http\Resources;
use Illuminate\Http\Resources\Json\JsonResource;
class AidRequestResource extends JsonResource { public function toArray($r):array { $viewer=$r->user(); $operations=$viewer&&in_array($viewer->role,['admin','staff'],true); $owner=$viewer&&$viewer->id===$this->beneficiary_id; $data=['id'=>$this->id,'category'=>$this->category,'quantity_needed'=>$this->quantity_needed,'matched_quantity'=>(int)$this->matches()->whereIn('status',['confirmed','fulfilled','proposed'])->sum('matched_quantity'),'urgency'=>$this->urgency,'justification'=>$this->justification,'alternative_categories'=>$this->alternative_categories,'status'=>$this->status,'created_at'=>$this->created_at]; if($operations||$owner)$data+=['beneficiary_id'=>$this->beneficiary_id,'item_details'=>$this->item_details,'pickup_location'=>$this->pickup_location,'availability_window'=>$this->availability_window,'supporting_document_url'=>$this->supporting_document_path?url('/api/requests/'.$this->id.'/document'):null,'cancellation_reason'=>$this->cancellation_reason,'cancelled_at'=>$this->cancelled_at,'is_walk_in'=>$this->is_walk_in,'walk_in_status'=>$this->walk_in_status,'verification_tier'=>$this->verification_tier,'verification_state'=>$this->verification_state,'verification_decision_reason'=>$this->verification_decision_reason,'verification_decided_at'=>$this->verification_decided_at,'student_id_number'=>$this->student_id_number,'verified_at'=>$this->updated_at,'beneficiary'=>new UserResource($this->whenLoaded('beneficiary'))]; if($operations)$data+=['staff_internal_notes'=>$this->staff_internal_notes,'referral_destination'=>$this->referral_destination,'verification_checklist'=>$this->verification_checklist,'verification_notes'=>$this->verification_notes,'verified_by_user_id'=>$this->verified_by_user_id,'verified_by'=>new UserResource($this->whenLoaded('verifiedBy'))]; return $data; } }
